1	import type { Exploration, TopicKey } from '@/types'
2	import { STORAGE_KEYS } from './keys'
3	
4	interface CreateInput {
5	  topic: TopicKey
6	  topicCustomLabel?: string
7	}
8	
9	function readAll(): Exploration[] {
10	  try {
11	    const raw = localStorage.getItem(STORAGE_KEYS.explorations)
12	    if (!raw) return []
13	    return JSON.parse(raw) as Exploration[]
14	  } catch {
15	    return []
16	  }
17	}
18	
19	function writeAll(list: Exploration[]): void {
20	  try {
21	    localStorage.setItem(STORAGE_KEYS.explorations, JSON.stringify(list))
22	  } catch {
23	    // localStorage unavailable (quota exceeded, private mode) — fail silently for this demo
24	  }
25	}
26	
27	function generateId(): string {
28	  if (typeof crypto !== 'undefined' && 'randomUUID' in crypto) {
29	    return crypto.randomUUID()
30	  }
31	  return `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`
32	}
33	
34	export function listExplorations(): Exploration[] {
35	  const all = readAll()
36	  return [...all].sort((a, b) =>
37	    new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()
38	  )
39	}
40	
41	export function getExploration(id: string): Exploration | null {
42	  return readAll().find(r => r.id === id) ?? null
43	}
44	
45	export function createExploration(input: CreateInput): Exploration {
46	  const now = new Date().toISOString()
47	  const record: Exploration = {
48	    id: generateId(),
49	    topic: input.topic,
50	    topicCustomLabel: input.topicCustomLabel,
51	    answers: [],
52	    status: 'in-progress',
53	    createdAt: now,
54	    updatedAt: now
55	  }
56	  writeAll([...readAll(), record])
57	  return record
58	}
59	
60	export function updateExploration(
61	  id: string,
62	  patch: Partial<Omit<Exploration, 'id' | 'createdAt'>>
63	): Exploration {
64	  const all = readAll()
65	  const idx = all.findIndex(r => r.id === id)
66	  if (idx < 0) throw new Error(`exploration ${id} not found`)
67	  const updated: Exploration = {
68	    ...all[idx],
69	    ...patch,
70	    // 呼叫端可明確指定 updatedAt（Demo 資料需要回填較早的時間），否則一律更新為現在
71	    updatedAt: patch.updatedAt ?? new Date().toISOString()
72	  }
73	  all[idx] = updated
74	  writeAll(all)
75	  return updated
76	}
77	
78	export function findInProgress(): Exploration | null {
79	  return listExplorations().find(r => r.status === 'in-progress') ?? null
80	}
81	
82	export function deleteExploration(id: string): void {
83	  writeAll(readAll().filter(r => r.id !== id))
84	}
