1	using chatai.Core.Helper;
2	using Microsoft.AspNetCore.Mvc.Filters;
3	using Microsoft.AspNetCore.Mvc;
4	using chatai_backend.Model;
5	using chatai_backend.Attribute;
6	using ntu.Common.Utility.Extension;
7	using ntu.Common.Utility.Exception;
8	using Microsoft.AspNetCore.Authorization;
9	
10	namespace chatai_backend.Filter
11	{
12	    public class ValidateSignatureFilter : IActionFilter
13	    {
14	        private readonly RsaHelper _rsaHelper;
15	        private readonly ILogger<ValidateSignatureFilter> _logger;
16	        private readonly SignatureContext _signatureContext;
17	
18	        public ValidateSignatureFilter(RsaHelper rsaHelper, ILogger<ValidateSignatureFilter> logger, SignatureContext signatureContext)
19	        {
20	            _rsaHelper = rsaHelper;
21	            _logger = logger;
22	            _signatureContext = signatureContext;
23	        }
24	
25	        public void OnActionExecuting(ActionExecutingContext context)
26	        {
27	            if (IsAllowAnonymous(context)) return;
28	
29	            if (!IsNeedSignature(context)) return;
30	
31	#if !DEBUG
32	
33	            if (!context.HttpContext.Request.Headers.TryGetValue("Authorization", out var encryptedSignature))
34	                throw new CustomException("缺少 Authorization Header.");
35	
36	            string decryptedSignature = _rsaHelper.Decrypt(encryptedSignature);
37	            _logger.LogInformation($"解密成功: {decryptedSignature}");
38	
39	            // 驗證 API Key 或 timestamp 是否有效
40	            if (!IsValidSignature(decryptedSignature))
41	                throw new CustomException("簽名驗證失敗");
42	
43	#endif
44	
45	        }
46	
47	        public void OnActionExecuted(ActionExecutedContext context)
48	        {
49	            // 無需處理
50	        }
51	
52	        private static bool IsNeedSignature(ActionExecutingContext context)
53	        {
54	            return context.ActionDescriptor.EndpointMetadata
55	                .Any(em => em is NeedSignatureAttribute);
56	        }
57	
58	        private static bool IsAllowAnonymous(ActionExecutingContext context)
59	        {
60	            return context.ActionDescriptor.EndpointMetadata
61	                .Any(em => em is AllowAnonymousAttribute);
62	        }
63	
64	        private bool IsValidSignature(string signature)
65	        {
66	            var signatureArr = signature.Split(" ");
67	            if (signatureArr.Length != 3)
68	                return false;
69	
70	            var fingerprint = signatureArr[0].ToNullString();
71	            var timestamp = signatureArr[1].ToLong();
72	            var apiFlow = signatureArr[2].ToInt();
73	
74	            if (string.IsNullOrEmpty(fingerprint) || timestamp == 0)
75	                return false;
76	
77	            DateTime localDateTime = DateTimeOffset.FromUnixTimeMilliseconds(timestamp).UtcDateTime.ToLocalTime();
78	            TimeSpan difference = DateTime.Now - localDateTime;
79	            double minutes = Math.Abs(difference.TotalMinutes);
80	
81	            if (minutes > 10)
82	                return false;
83	
84	            _signatureContext.fingerprint = fingerprint;
85	            _signatureContext.timestamp = timestamp;
86	            _signatureContext.apiFlow = apiFlow;
87	
88	            return true;
89	        }
90	    }
91	}
